import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"WorldArena: A Unified Benchmark for Evaluating Perception and Functional Utility of Embodied World Models","description":"","frontmatter":{"title":"WorldArena: A Unified Benchmark for Evaluating Perception and Functional Utility of Embodied World Models","arxiv":"2602.08971","date":"2026-02-09","authors":"Yu Shang, Zhuohang Li, Yiding Ma, Weikang Su, Xin Jin, Ziyou Wang, Lei Jin, Xin Zhang, Yinzhou Tang, et al.","categories":"cs.CV, cs.RO","topics":"具身世界模型评测, 感知-功能鸿沟, EWMScore","outline":[2,2]},"headers":[],"relativePath":"papers/2602.08971.md","filePath":"papers/2602.08971.md","lastUpdated":null}'),e={name:"papers/2602.08971.md"};function l(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="worldarena-a-unified-benchmark-for-evaluating-perception-and-functional-utility-of-embodied-world-models" tabindex="-1">WorldArena: A Unified Benchmark for Evaluating Perception and Functional Utility of Embodied World Models <a class="header-anchor" href="#worldarena-a-unified-benchmark-for-evaluating-perception-and-functional-utility-of-embodied-world-models" aria-label="Permalink to &quot;WorldArena: A Unified Benchmark for Evaluating Perception and Functional Utility of Embodied World Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2602.08971" target="_blank" rel="noreferrer">2602.08971</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-02-09</td></tr><tr><td><strong>作者</strong></td><td>Yu Shang, Zhuohang Li, Yiding Ma, Weikang Su, Xin Jin, Ziyou Wang, Lei Jin, Xin Zhang, Yinzhou Tang, Haisheng Su, Chen Gao, Wei Wu, Xihui Liu, Dhruv Shah, Zhaoxiang Zhang, Zhibo Chen, Jun Zhu, Yonghong Tian, Tat-Seng Chua, Wenwu Zhu, Yong Li</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>在同一批 RoboTwin 2.0 数据上，把 14 个具身世界模型既按 6 维 16 项视频质量打分，又按数据引擎/策略评估器/动作规划器三种真实用途实测，量出&quot;画面好≠能干活&quot;的鸿沟。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页当前指向 v2（2026-02-11），本文按 v2 全文撰写。作者共 21 位，frontmatter 取前 9 位加 et al.，元信息表给出完整名单。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>具身世界模型现在有两种完全不同的读法。一种把它当视频生成器，用 FVD、美学分、主体一致性来评；另一种把它当环境代理，指望它替代真机去合成数据、评估策略、甚至直接当规划器用。这两种读法从未在同一批模型、同一批数据上被同时量过，于是社区默认了一个未经检验的前提：画面生成得越好，作为环境代理就越有用。</p><p>WorldArena 要做的就是把这个前提摆到台面上验一遍。如果二者高度相关，那么继续卷视频质量就是对的；如果不相关，整个领域的优化方向就需要调整。这件事的价值不在于榜单本身，而在于它给出的是一个<strong>否定性结论的证据量级</strong>——目前的视觉保真度还没到能支撑具身任务的程度。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>表 1 把已有 benchmark 按三类维度对齐后，缺口一目了然。WorldModelBench 只测物理遵循与可控性；WorldScore、4DWorldBench 在视频质量维度上覆盖较全（含 3D 精度），但完全不碰具身任务；EWMBench 测运动质量、内容一致性与可控性，也不测下游用途。真正碰到功能侧的只有少数几家：WorldEval 只做策略评估、不测视频质量，World-in-World 与 WorldSimBench 则各自只覆盖动作规划这一个功能角色。</p><p>作者对已有工作的两点批评是具体的。第一，功能角色覆盖不全——即使是做闭环执行的 benchmark，也没人系统评过&quot;当合成数据引擎&quot;这一用途。第二，被测模型太窄：多数 benchmark 只评不到十个模型，且集中在文本条件的通用视频生成模型上，而近两年出现的机器人专用世界模型（Genie Envisioner、GigaWorld、TesserAct、WoW、CtrlWorld 等）基本没被系统评过。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从&quot;世界模型到底拿来干什么&quot;这个问题倒推，答案只有三个：给策略造数据、给策略打分、直接当策略。这三件事各自有一个可以直接测量的量——下游策略的成功率、世界模型评分与真仿真器评分的相关性、闭环执行的成功率。三个量都不需要新发明指标，只需要一个能同时跑仿真真值与世界模型 rollout 的环境。RoboTwin 2.0 恰好提供了这样的环境：50 个双臂操作场景、有仿真器可以给出真值成功率。</p><p>视频质量那一侧的思路是&quot;尽量不发明&quot;。16 个指标基本都是从 VBench、WorldScore、EWMBench 搬来的成熟量：MUSIQ 测清晰度、LAION 美学预测器测观感、V-JEPA 特征的 MMD 测与真值分布的相似度、RAFT 光流测动态度、DINO/CLIP 特征余弦测主体与背景一致性、SAM 3 提取臂的框后算 NDTW 测轨迹精度、Qwen3-VL 当裁判测交互质量与透视合理性。新增的主要是把它们按&quot;感知六维&quot;重新组织，并把动作条件化的模型也纳入同一套协议。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>评价一个世界模型的正确方式，是把它放进它声称要替代的那个位置上去测，而不是测它的输出像不像视频。一旦这样测，两类信号立刻分离：闭源通用视频模型在人眼和感知指标上遥遥领先，轨迹精度却落到全表下游；动作条件化的 CtrlWorld 画质一般，却是被测的两个策略评估器里唯一与真仿真器高度吻合的那个。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>数据统一用 RoboTwin 2.0：50 个任务场景、2500 段视频，其中 2000 段训世界模型、500 段测。被测模型 14 个，分三类——通用视频模型（CogVideoX、Wan 2.2、Wan 2.6、Veo 3.1）、文本条件具身模型（Genie Envisioner、GigaWorld-0、TesserAct、Cosmos-Predict 2.5、WoW、RoboMaster、Vidar）、动作条件具身模型（IRASim、Cosmos-Predict 2.5 的 action 版、CtrlWorld）。有训练代码的模型都按官方实现在该数据集上做了 post-training。</p><p>三个功能任务的具体做法：</p><ul><li><strong>数据引擎</strong>：先在 RoboTwin 2.0 上微调世界模型，条件于首帧与指令生成视频；再冻结世界模型、接一个 inverse dynamics model，按 VPP 的 diffusion policy head 设计，用世界模型的中间特征引导动作去噪，产出配对的视频-动作序列。用这些合成轨迹训 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，看成功率增益。每个任务跑 100 次取平均，每个世界模型提供 25 条合成轨迹。</li><li><strong>策略评估器</strong>：用 10%/20%/30%/50%/100% 数据训出五个能力不同的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，让它们与动作可控的世界模型交互 rollout，直到帧数超过真值视频 20%；用 VLM 判定是否成功；与 RoboTwin 仿真器给出的成功率算相关。</li><li><strong>动作规划器</strong>：世界模型 + IDM，吃指令与首帧直接吐动作序列，放进 RoboTwin 仿真器执行测成功率。</li></ul><p><strong>EWMScore</strong> 的定义很朴素：把 16 个指标按经验边界（全部视频上各指标的 1% 与 99% 分位）线性归一到 [0,100]，然后取<strong>算术平均</strong>。人类评测招了 70 名标注者，评了 3500 段视频，含 1–5 分打分与两两胜率两种形式。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无复杂形式化推导，唯一需要展开的是 EWMScore 的构造及其后果。记第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个指标原始值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、经验下界 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0197em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（1% 分位）与上界 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（99% 分位），则</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">EWMScore</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.0788em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">16</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">100</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">16</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">clip</span></span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">(</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0197em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0197em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">)</span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">.</span></span></span></span></span></p><p>等权算术平均意味着每个指标的边际影响完全由它在 14 个模型上的<strong>离散程度</strong>决定，而不是由它与具身效用的相关性决定。表 2/表 3 里，Semantic Alignment 全场落在 0.7733–0.8977 这个 0.12 宽的区间，Perspectivity 落在 0.5284–0.8276，而 Action Following 落在 0.0076–0.1418。归一化用的是 1%/99% 分位而非各指标的跨模型极差，所以像 Action Following 这种绝对值贴地板的指标，其归一化后的贡献取决于经验边界的取法，论文把边界表放在附录表 6 但正文没有讨论这个选择对排名的影响。</p><p>一个更根本的问题是 Action Following 的定义方向。它测的是&quot;同一首帧、三条不同指令下生成视频的两两特征差异均值&quot;，即<strong>多样性</strong>。动作条件化的模型（CtrlWorld 0.0210、IRASim 0.0526、Cosmos-action 0.0133）在这一项上系统性低于文本条件模型（Cosmos-text 0.1418、GigaWorld-0 0.1134），而前者恰恰是在策略评估上表现最好的一类。把&quot;输出随指令变化多&quot;当作可控性的代理，在动作条件设定下并不成立——一个真正精确跟随动作的模型，在指令改变而动作序列近似时本就应该输出相近的画面。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>视频质量。</strong> 闭源/大规模通用模型在感知侧占优：Wan 2.6 的 Image Quality 0.6824 是全表最高（第二是 Cosmos-Predict 2.5 文本版的 0.6668，Veo 3.1 的 0.6605 紧随其后），Veo 3.1 的 Aesthetic 0.4632 与 Interaction Quality 0.7872、Instruction Following 0.9328 都是第一。具身模型则在结构与交互相关的指标上占优：CtrlWorld 的 Trajectory Accuracy 0.4766 与 Subject Consistency 0.8411 为全表最高，Depth Accuracy 0.9300 仅次于 IRASim 的 0.9312。关键对比是轨迹精度——Veo 3.1 与 Wan 2.6 只有 0.1231 与 0.1182，落在全表下游。</p><p><strong>数据引擎（表 4）。</strong> 基线是零样本 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（Task 1 / Task 2 = 2% / 5%）与真实数据训练的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（77% / 66%）。六个世界模型里只有 WoW（45%/71%）与 RoboMaster（7%/68%）在 Task 2 上超过真实数据，而 Task 1 上全部远低于 77%。TesserAct 在 Task 1 上只有 1%，<strong>低于什么都不训的零样本 2%</strong>——合成数据在这个任务上是有害的。作者的结论是当前生成数据的质量还不足以支撑策略训练，这个结论表格完全支持。</p><p><strong>策略评估器（图 4）。</strong> 只测了两个模型：CtrlWorld 与仿真器的 Pearson 相关是 0.986，Cosmos-Predict 2.5 只有 0.483。一个诚实的观察被作者写进了正文：两个模型给出的成功率都<strong>系统性高于</strong>仿真器，暗示对成功轨迹的部分过拟合。除图中这两个相关系数外，本项没有给出逐策略的成功率数值。</p><p><strong>动作规划器（表 5）。</strong> 全线远低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 77%/66%：WoW 20%/21%、Genie Envisioner 10%/20%、RoboMaster 8%/20%、Wan 2.2 12%/20%、Vidar 2%/19%、TesserAct 1%/35%。<strong>注意 TesserAct 在表 4 与表 5 中的两个数字逐位相同（1% 与 35%）</strong>，而两表对应的是完全不同的实验协议（用合成数据训 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> vs 世界模型直接闭环规划），这很可能是一处复制错误。</p><p><strong>跨维度相关（图 5）。</strong> EWMScore 与人类评测 Pearson <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.825</span></span></span></span>，与数据合成表现 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.600</span></span></span></span>，与动作规划表现 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.360</span></span></span></span>。这是全文的头条结论——但要注意这三个相关系数的样本量不同：人类那一路的图例列了全部 14 个模型，后两路的图例都只有 6 个（Genie Envisioner、TesserAct、RoboMaster、Vidar、WoW、Wan 2.2），见 § 9。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版。</strong> WorldArena 在 RoboTwin 2.0 上把 14 个具身世界模型同时按 6 维 16 项视频质量与三种功能角色（数据引擎、策略评估器、动作规划器）评测，并配 70 人 3500 段视频的人类评估。感知侧闭源通用模型领先（Wan 2.6 Image Quality 0.6824、Veo 3.1 Instruction Following 0.9328），功能侧动作条件具身模型领先（CtrlWorld Trajectory Accuracy 0.4766、Depth 0.9300）。合成数据只在两个模型的一个任务上超过真实数据，动作规划全线远逊 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。EWMScore 与人类判断相关 0.825，与数据合成 0.600，与动作规划仅 0.360。结论是感知保真度是人类满意的必要条件，但远不足以支撑具身决策。</p><p><strong>三句话版。</strong> 同一批模型同时按画质与三种真实用途评测，画质榜与功能榜的排序明显不同。合成数据与闭环规划的绝对水平都还远低于真机训练的策略。综合画质指标与人类判断高度相关，与具身效用只有中弱相关。</p><p><strong>一句话版。</strong> 具身世界模型当前的瓶颈不在画面好不好看，而在生成内容是否携带决策可用的信息。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是<strong>头条相关系数所依赖的样本量</strong>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.600</span></span></span></span>（数据合成）与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.360</span></span></span></span>（动作规划）是在表 4 与表 5 各自的六个世界模型上算出来的。在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 时，双尾 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span> 需要 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.81</span></span></span></span>；因此 0.600 与 0.360 都远未达到统计显著，甚至无法区分于零相关。换句话说，&quot;感知-功能鸿沟&quot;这一核心结论在统计上还没有被建立，它更接近一个基于六个点的定性观察。人类评测那一路的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.825</span></span></span></span> 建立在 14 个模型上，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">14</span></span></span></span> 时显著阈值约 0.53，这一条是成立的。</p><p>如果这个假设被认真检验（例如把六个模型扩到十四个、或对每个模型报告 bootstrap 置信区间），完全可能出现两种结果：鸿沟被确认并量化，或者相关性其实不低而是被少数几个异常点压低（TesserAct 在两个任务上的 1% 与 35% 差异极大，是明显的高杠杆点）。论文既没有报告置信区间，也没有做留一模型的稳健性检查。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要重训任何世界模型：</p><ul><li>取论文公开的 14 个模型的 16 项指标值（表 2/表 3 已完整给出）与三项功能得分，自己重算 EWMScore 并做三件事：(1) 对数据引擎/动作规划两组用 bootstrap（对模型重采样）给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 的 95% 置信区间；(2) 做留一模型分析，看 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 的波动范围；(3) 逐指标算与功能得分的单项相关，找出真正有预测力的那几项。</li><li>判据：若 (1) 的区间跨过 0，则&quot;弱相关&quot;这一结论需要降级为&quot;数据不足以判定&quot;；若 (3) 中 Trajectory Accuracy 单项与闭环成功率的相关明显高于 EWMScore 整体，则等权平均是有害的，应当改为加权或直接用单项作为功能代理。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释一：闭源模型的&quot;感知强、功能弱&quot;是微调混淆的产物。</strong> 论文明确写了&quot;所有有训练代码的模型都在该数据集上做了 post-training&quot;，这意味着 Veo 3.1 与 Wan 2.6 是<strong>零样本</strong>在 RoboTwin 2.0 上跑的，其余多数模型是微调过的。表 2 里 JEPA Similarity（与真值分布的相似度）恰好印证了这一点：CogVideoX 0.9384、Cosmos-action 0.9296、CtrlWorld 0.9185，而 Veo 3.1 只有 0.5694。所以&quot;通用模型画面漂亮但不懂具身&quot;完全可以被重述为&quot;未在该域微调的模型自然与真值分布不匹配&quot;。要排除这个解释，需要在同一个开源骨干上做&quot;微调 vs 不微调&quot;的成对比较，看感知-功能鸿沟是否依然存在。</p><p><strong>替代解释二：功能侧的低分可能来自评测管线而非世界模型。</strong> 数据引擎与动作规划两路都在世界模型之后接了一个 IDM（VPP 式 diffusion head），策略评估那一路用 VLM 判成功。这三个组件本身的精度从未被单独标定——论文没有报告&quot;用真值视频喂同一个 IDM 能拿到多少成功率&quot;这一上界。如果这个上界本身就只有 40%，那么表 5 里 20% 左右的成绩就不再说明世界模型弱，而说明 IDM 弱。这个 oracle 对照是全文最该有而没有的一行。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文证明了感知指标预测不了具身效用，但它给出的替代方案（跑三个下游任务）成本极高——每个模型都要微调、接 IDM、训策略、在仿真器里跑数百次。这使得 benchmark 无法被日常用于 checkpoint 选择，而 checkpoint 选择恰恰是研究者最需要的场景。</p><p><strong>(b) 可借鉴的相邻工具</strong>：本批的 <a href="/notes/papers/2606.18610">SC3-Eval</a> 提供了一个关键线索——世界模型自身的 inverse dynamics 模式可以充当&quot;生成内容是否携带动作信息&quot;的零成本探针。这与表征学习里用 linear probe 衡量特征信息量是同一个思路。</p><p><strong>(c) 第一个实验</strong>：把&quot;功能效用&quot;重新框定为<strong>动作可解码性</strong>：冻结一个统一的、在真值视频上训练好的 inverse dynamics 探针，对每个世界模型的生成 rollout 回读动作，测回读动作与指令动作的误差。这是一个不需要训策略、不需要跑仿真器的单次前向量。第一个实验就是在本文已有的 14 个模型上算这个探针分数，看它与表 4/表 5 的功能得分相关性能否显著超过 EWMScore 的 0.600/0.360。如果能，具身世界模型的日常评测就可以从&quot;跑三个下游任务&quot;降级为&quot;跑一个探针&quot;，同时这个探针还天然给出了可训练的优化目标。</p>',48)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
